/**
 * Clustering strategy that schedules clustering incrementally based on the table's commit history.
 * <p>
 * The strategy scans completed commits after a configured earliest commit (exclusive), collects the files written by
 * each commit grouped by partition and forms clustering groups respecting the per-group size limits. Files whose file
 * groups have been superseded by replace commits are excluded. Progress is tracked via a checkpoint (the requested time
 * of the last processed commit) that is persisted in the plan's extra metadata.
 */
public class CommitBasedClusteringPlanStrategy<T, I, K, O> extends PartitionAwareClusteringPlanStrategy<T, I, K, O> {

  private static final Logger LOG = LoggerFactory.getLogger(CommitBasedClusteringPlanStrategy.class);

  public static final String CLUSTERING_COMMIT_CHECKPOINT_KEY = "clustering.commit.checkpoint";

  private String checkpoint;

  public CommitBasedClusteringPlanStrategy(HoodieTable table, HoodieEngineContext engineContext, HoodieWriteConfig writeConfig) {
    super(table, engineContext, writeConfig);
    this.checkpoint = null;
  }

  public Option<HoodieClusteringPlan> generateClusteringPlan() {
    HoodieTableMetaClient metaClient = getHoodieTable().getMetaClient();

    String earliestCommit = getWriteConfig().getClusteringEarliestCommitToCluster();
    if (earliestCommit == null) {
      LOG.error("Please set the config {} for commit based clustering plan strategy",
          org.apache.hudi.config.HoodieClusteringConfig.PLAN_STRATEGY_EARLIEST_COMMIT_TO_CLUSTER.key());
      return Option.empty();
    }

    // Only consider commits strictly after the earliest commit time.
    HoodieTimeline commitTimeline = metaClient.getCommitsTimeline().findInstantsAfter(earliestCommit).filterCompletedInstants();

    List<CommitFiles> commitFilesList = new ArrayList<>();
    List<String> replacedFileIds = new ArrayList<>();
    for (HoodieInstant instant : commitTimeline.getInstants()) {
      CommitFiles commitFiles = getFileSlicesEligibleForCommitBasedClustering(instant);
      commitFilesList.add(commitFiles);
      replacedFileIds.addAll(commitFiles.getReplacedFileIds());
    }

    List<HoodieClusteringGroup> clusteringGroups = new ArrayList<>();
    Map<String, Long> partitionToSize = new HashMap<>();
    Map<String, List<FileSlice>> partitionToFiles = new HashMap<>();
    String lastCommit = null;

    for (CommitFiles commitFiles : commitFilesList) {
      lastCommit = commitFiles.getInstantTime();
      for (Map.Entry<String, List<FileSlice>> entry : commitFiles.getPartitionToFileSlices().entrySet()) {
        String partition = entry.getKey();
        List<FileSlice> fileSlices = entry.getValue().stream()
            // exclude file groups that have been replaced by replace commits
            .filter(fileSlice -> !replacedFileIds.contains(fileSlice.getFileId()))
